mapper.select:
SELECT BUDGET_ID AS "budgetId", BUDGET_NO AS "budgetNo", BUDGET_NAME AS "budgetName", BUDGET_YEAR AS "budgetYear", BUDGET_TYPE AS "budgetType", BUDGET_AMOUNT AS "budgetAmount", COALESCE(USED_AMOUNT, 0) AS "usedAmount", COST_CENTER_ID AS "costCenterId", DEPARTMENT_ID AS "departmentId", PREPARER_ID AS "preparerId", PREPARER_NAME AS "preparerName", PREPARATION_DATE AS "preparationDate", APPROVAL_STATUS AS "approvalStatus", APPROVER_ID AS "approverId", APPROVER_NAME AS "approverName", APPROVAL_TIME AS "approvalTime", APPROVAL_COMMENT AS "approvalComment", REMARK AS "remark", BUDGET_DETAILS_JSON AS "budgetDetailsJson", CREATE_TIME AS "createTime" FROM TBL_BUDGET_PREPARATION WHERE 1 = 1
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}
AND BUDGET_YEAR = #{budgetYear}
AND BUDGET_TYPE = #{budgetType}
AND COST_CENTER_ID = #{costCenterId}
AND APPROVAL_STATUS = #{approvalStatus}
ORDER BY CREATE_TIME DESC OFFSET #{offset} ROWS FETCH NEXT #{pageSize} ROWS ONLY

SELECT COUNT(1)
FROM TBL_BUDGET_PREPARATION
WHERE 1 = 1

      AND BOOK_ID = #{bookId}


      AND TENANT_ID = #{tenantId}


      AND BUDGET_YEAR = #{budgetYear}


      AND BUDGET_TYPE = #{budgetType}


      AND COST_CENTER_ID = #{costCenterId}


      AND APPROVAL_STATUS = #{approvalStatus}

SELECT COUNT(1)
FROM TBL_BUDGET_PREPARATION
WHERE BUDGET_NO = #{budgetNo}
  AND BOOK_ID = #{bookId}
  AND TENANT_ID = #{tenantId}

      AND BUDGET_ID != #{budgetId}

SELECT
    COUNT(1) AS "totalCount",
    SUM(BUDGET_AMOUNT) AS "totalAmount",
    SUM(CASE WHEN APPROVAL_STATUS = 3 THEN BUDGET_AMOUNT ELSE 0 END) AS "approvedAmount",
    SUM(CASE WHEN APPROVAL_STATUS = 1 THEN 1 ELSE 0 END) AS "pendingCount"
FROM TBL_BUDGET_PREPARATION
WHERE BUDGET_YEAR = #{budgetYear}
  AND BOOK_ID = #{bookId}
  AND TENANT_ID = #{tenantId}

SELECT
    (SELECT COUNT(1)
     FROM TBL_BUDGET_PREPARATION
     WHERE 1 = 1
        AND BOOK_ID   = #{bookId}   
     AND TENANT_ID = #{tenantId} 
    ) AS budget_projects,
    (SELECT COALESCE(SUM(BUDGET_AMOUNT), 0)
     FROM TBL_BUDGET_PREPARATION
     WHERE 1 = 1
        AND BOOK_ID   = #{bookId}   
     AND TENANT_ID = #{tenantId} 
    ) AS total_budget,
    (SELECT COALESCE(SUM(ACTUAL_AMOUNT), 0)
     FROM TBL_VARIANCE_ANALYSIS
     WHERE 1 = 1
        AND BOOK_ID   = #{bookId}   
     AND TENANT_ID = #{tenantId} 
    ) AS actual_cost,
    (SELECT COALESCE(ROUND(AVG(VARIANCE_RATE), 2), 0)
     FROM TBL_VARIANCE_ANALYSIS
     WHERE 1 = 1
        AND BOOK_ID   = #{bookId}   
     AND TENANT_ID = #{tenantId} 
    ) AS variance_rate
FROM DUAL
